// Split daemon stdout by newlines, filter lines > 10 chars
// Outputs individual messages for JSON parsing
var outputMsgs = [];
var objects = msg.payload.split("\n");
for (var o in objects) {
    if (objects[o].length > 10) {
        outputMsgs.push({payload: objects[o]});
    }
}
return [outputMsgs];

// Process parsed IEC104 JSON messages from the server binary
// Detects connection events, control commands, and data messages
// Output 1: All parsed data → link out (IEC-Server-Out)
// Output 2: Connection status → MQTT iec104-status
// Output 3: Control commands → MQTT iec104-command
// Output 4: Command audit → MQTT command-audit (Story 2.4)

var data = msg.payload;
if (!data || typeof data !== 'object') {
    return null;
}

// IOA-to-telemetry-key mapping (Task 2)
var ioaMap = {
    1: {key: 'power_draw_kw', type: 'M_ME_NC_1'},
    2: {key: 'export_limit_kw', type: 'M_ME_NC_1'},
    3: {key: 'inverter_status', type: 'M_SP_NA_1'}
};

var linkOutMsg = {payload: data};
var statusMsg = null;
var commandMsg = null;
var auditMsg = null;

// Detect connection/disconnection events
if (data.type === 'connection' || data.event === 'connected' || data.event === 'disconnected') {
    var connected = (data.event === 'connected' || data.connected === true);
    flow.set('iec104Connected', connected);

    statusMsg = {
        payload: JSON.stringify({iec104_connected: connected, ts: Date.now()}),
        topic: 'nexus/internal/iec104-status'
    };

    node.status({
        fill: connected ? 'green' : 'red',
        shape: 'dot',
        text: connected ? 'EVN connected' : 'EVN disconnected'
    });
}

// Detect control commands from grid operator (C_SE_NC_1 = type 50, C_IC_NA_1 = type 100)
var typeNum = parseInt(data.type, 10);
if (typeNum === 50 || typeNum === 100 || data.direction === 'command') {
    var ioa = parseInt(data.address, 10);
    var mapping = ioaMap[ioa];

    // For interrogation commands (type 100), respond with current telemetry
    if (typeNum === 100) {
        var latestTelemetry = flow.get('latestTelemetry') || {};
        // Telemetry response will be handled by feeding values back to daemon stdin
        // via the link out → other flows → link in path
    }

    // For set-point commands (type 50), forward to MQTT
    if (typeNum === 50 && mapping) {
        // Generate unique event_id for audit correlation (Story 2.4)
        var eventId = Date.now().toString(36) + Math.random().toString(36).substr(2, 4);
        var now = Date.now();

        var commandPayload = {
            device_id: flow.get('latestDeviceId') || 'inverter-01',
            zone_id: env.get('ZONE_ID') || 'zone-01',
            action: 'set_' + mapping.key,
            value: parseFloat(data.value) || 0,
            unit: 'kw',
            source: 'iec104',
            timestamp: now,
            event_id: eventId
        };

        commandMsg = {
            payload: JSON.stringify(commandPayload),
            topic: 'nexus/internal/iec104-command'
        };

        // Command receipt audit entry (Story 2.4)
        auditMsg = {
            payload: JSON.stringify({
                event_id: eventId,
                source: 'iec104',
                device_id: commandPayload.device_id,
                zone_id: commandPayload.zone_id,
                action: commandPayload.action,
                value: commandPayload.value,
                lifecycle_stage: 'command_received',
                result: {status: 'forwarded_to_writeback'},
                timestamp: now
            }),
            topic: 'nexus/internal/command-audit'
        };
    }
}

return [linkOutMsg, statusMsg, commandMsg, auditMsg];

