// Store latest inverter telemetry values in flow context
// for IEC104 interrogation responses
// Input topic: nexus/{zone_id}/{device_id}/telemetry

var topicParts = msg.topic.split('/');
if (topicParts.length < 4) {
    return null;
}

var zoneId = topicParts[1];
var deviceId = topicParts[2];
var data = msg.payload;

if (!data || typeof data !== 'object') {
    return null;
}

// Extract values - handle ThingsBoard format {ts, values} or flat format
var values = data.values || data;

var latestTelemetry = flow.get('latestTelemetry') || {};
latestTelemetry[deviceId] = {
    zone_id: zoneId,
    device_id: deviceId,
    power_draw_kw: values.power_draw_kw,
    export_limit_kw: values.export_limit_kw,
    inverter_status: values.inverter_status,
    ts: Date.now()
};

flow.set('latestTelemetry', latestTelemetry);
flow.set('latestDeviceId', deviceId);

node.status({fill: 'green', shape: 'dot', text: deviceId + ' updated'});

return null;

// Format error message for logging and publishing
var errorSource = msg.error ? msg.error.source : {};
var errorMsg = msg.error ? msg.error.message : 'Unknown error';
var nodeName = errorSource.name || errorSource.id || 'unknown';

var errorType = 'UnknownError';
var typeMatch = errorMsg.match(/\[iec104-server\]\s+(\w+):\s*(.*)/);
if (typeMatch) {
    errorType = typeMatch[1];
    errorMsg = typeMatch[2];
} else {
    errorType = nodeName.replace(/[^a-zA-Z0-9]/g, '_') + '_Error';
}

node.warn('[iec104-server] ' + errorType + ': ' + errorMsg);

msg.payload = JSON.stringify({
    error_type: errorType,
    source: nodeName,
    message: errorMsg.substring(0, 200),
    ts: Date.now()
});
msg.topic = 'nexus/internal/iec104-errors';

return msg;

// Convert writeback-status confirmation into IEC104 daemon stdin JSON
// for grid operator acknowledgment (positive confirm)
// Output 1: IEC104 ack → daemon stdin
// Output 2: Audit entry → command-audit MQTT
//
// Only send ack for IEC104-originated commands (source === 'iec104')

var status = msg.payload;
if (!status || typeof status !== 'object') {
    return null;
}

// Only acknowledge IEC104-originated commands
if (status.source !== 'iec104') {
    return null;
}

// Reverse IOA mapping: action → IOA address
var actionToIoa = {
    'set_power_draw_kw': 1,
    'set_export_limit_kw': 2,
    'set_inverter_status': 3
};

var ioa = actionToIoa[status.action];
if (!ioa) {
    node.warn('[iec104-server] AckError: no IOA mapping for action ' + status.action);
    return null;
}

// Build IEC104 positive acknowledgment for daemon stdin
// C_SE_NC_1 (type 50) with COT=7 (activation confirm)
var ackPayload = JSON.stringify({
    type: '50',
    value: status.value,
    address: ioa,
    qualifier: '0',
    cot: '7'
});

var ackMsg = {
    payload: ackPayload
};

// Build audit entry for write_confirmed lifecycle stage
var auditMsg = {
    payload: JSON.stringify({
        event_id: status.event_id || '',
        source: 'iec104',
        device_id: status.device_id,
        zone_id: status.zone_id,
        action: status.action,
        value: status.value,
        lifecycle_stage: 'write_confirmed',
        result: {status: 'confirmed', register_address: status.register_address},
        timestamp: Date.now()
    }),
    topic: 'nexus/internal/command-audit'
};

node.log('[iec104-server] AckSent: ' + status.action + '=' + status.value + ' IOA=' + ioa + ' for device ' + status.device_id);

return [ackMsg, auditMsg];

// Convert writeback-errors into IEC104 daemon stdin JSON
// for grid operator error response (negative confirm)
// Output 1: IEC104 nack → daemon stdin
// Output 2: Audit entry → command-audit MQTT
//
// Only send nack for IEC104-originated commands (source === 'iec104')

var error = msg.payload;
if (!error || typeof error !== 'object') {
    return null;
}

// Only acknowledge IEC104-originated commands
if (error.source !== 'iec104') {
    return null;
}

// Reverse IOA mapping: action → IOA address
var actionToIoa = {
    'set_power_draw_kw': 1,
    'set_export_limit_kw': 2,
    'set_inverter_status': 3
};

var ioa = actionToIoa[error.action];
if (!ioa) {
    node.warn('[iec104-server] NackError: no IOA mapping for action ' + error.action);
    // Still publish audit even if we can't send IEC104 nack
    ioa = 0;
}

// Build IEC104 negative acknowledgment for daemon stdin
// C_SE_NC_1 (type 50) with COT=47 (negative activation confirm)
var nackMsg = null;
if (ioa > 0) {
    nackMsg = {
        payload: JSON.stringify({
            type: '50',
            value: 0,
            address: ioa,
            qualifier: '0',
            cot: '47'
        })
    };
}

// Build audit entry for write_failed lifecycle stage
var auditMsg = {
    payload: JSON.stringify({
        event_id: error.event_id || '',
        source: 'iec104',
        device_id: error.device_id,
        zone_id: error.zone_id,
        action: error.action,
        value: error.value,
        lifecycle_stage: 'write_failed',
        result: {status: 'failed', error: error.error, retries_exhausted: error.retries_exhausted},
        timestamp: Date.now()
    }),
    topic: 'nexus/internal/command-audit'
};

node.warn('[iec104-server] NackSent: ' + error.action + ' failed for device ' + error.device_id + ' — ' + error.error);

return [nackMsg, auditMsg];
